        }
        // Accept formats: (123) 456-7890, 123-456-7890, 1234567890, +1 (123) 456-7890, etc.
        const phoneRegex = /^[\d\s\-+()]+$/.test(value) && value.replace(/\D/g, '').length >= 10;
        if (!phoneRegex) {
            return 'Please enter a valid phone number';
        }
        return '';
    }

